import{_ as t,o as r,c as a,ae as o}from"./chunks/framework.BvHJbMD4.js";const u=JSON.parse('{"title":"New Research: The Alsberg Family - A Human Tragedy","description":"Documentation of the research results on the Jewish entrepreneurial family Alsberg and their role in the Horten narrative.","frontmatter":{"title":"New Research: The Alsberg Family - A Human Tragedy","description":"Documentation of the research results on the Jewish entrepreneurial family Alsberg and their role in the Horten narrative.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-alsberg-familie.md","filePath":"en/logbuch/2026-02-27-alsberg-familie.md"}'),n={name:"en/logbuch/2026-02-27-alsberg-familie.md"};function s(i,e,l,h,c,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="new-research-the-alsberg-family-a-human-tragedy" tabindex="-1">New Research: The Alsberg Family - A Human Tragedy <a class="header-anchor" href="#new-research-the-alsberg-family-a-human-tragedy" aria-label="Permalink to &quot;New Research: The Alsberg Family - A Human Tragedy&quot;">​</a></h1><p>Today we integrated the results of our deep research into the <strong>Alsberg family</strong> into the project. For the mockumentary, this is not just &quot;background information,&quot; but the moral anchor of the second and third acts.</p><p><strong>Key Findings:</strong></p><ul><li>The systematic destruction of the <strong>&quot;Gebrüder Alsberg AG&quot;</strong> through &quot;Aryanization.&quot;</li><li>The individual fates of <strong>Siegfried, Emma, Alfred, and Martha Alsberg</strong> – from the heights of the department store empire to deportation and murder.</li><li>The role of <strong>Helmut Horten</strong> as a direct beneficiary of these tragedies.</li></ul><p>These facts sharpen the satirical edge of our film: The contrast between the &quot;clean&quot; success of the economic miracle king and the blood-soaked ruins of his predecessors is the heart of the &quot;Horten Mystery.&quot;</p><p><em>Documented by Gemini CLI.</em></p>',6)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
